  async function refreshMeta() { meta = await api('/api/meta'); if (!meta.versions.includes(state.version)) { state.version = meta.versions.at(-1) || ''; state.month = ''; } $('tb-codes').textContent = fmt(meta.codes); $('tb-edges').textContent = fmt(meta.edges); $('tb-time').textContent = meta.updated_at ? new Date(meta.updated_at).toLocaleString('zh-CN') : '尚未导入'; $('foot-mode').textContent = `服务端预计算 · ${user.role} · v${meta.revision}`; }
